// This API fixture deliberately implements only the documented expressions used
// below. Rejecting unknown expressions keeps a broken UI request from silently
// passing an unfiltered mock response.
function filteredPackets(url){
 const expression=url.searchParams.get('filter')||'',query=(url.searchParams.get('query')||'').toLowerCase(),protocol=url.searchParams.get('protocol');
 let rows=packetRows.filter(row=>(!query||JSON.stringify(row).toLowerCase().includes(query))&&(!protocol||row.protocol===protocol));
 for(let clause of expression.split(/\s*&&\s*/).filter(Boolean)){
  clause=clause.trim().replace(/^\(+|\)+$/g,'').trim();
  let match;
  if((match=clause.match(/^frame\.severity\s*==\s*"(error|warn|note|normal)"$/)))rows=rows.filter(row=>(row.highlight||'normal')===match[1]);
  else if((match=clause.match(/^protocol\s*==\s*"?([A-Za-z0-9]+)"?$/)))rows=rows.filter(row=>row.protocol.toLowerCase()===match[1].toLowerCase());
  else if(clause==='frame.time_recorded')rows=rows.filter(row=>row.time&&!row.time.startsWith('0001-')&&Number.isFinite(Date.parse(row.time)));
  else if(clause==='frame.len > 0')rows=rows.filter(row=>row.length>0);
  else if(clause==='expert')rows=rows.filter(row=>row.expert?.length);
  else if((match=clause.match(/^frame\.number\s*==\s*(\d+)$/)))rows=rows.filter(row=>row.number===Number(match[1]));
  else throw Error('Unsupported UI94 packet fixture expression: '+clause);
 }
 const sort=url.searchParams.get('sort')||'number',direction=url.searchParams.get('direction')==='desc'?-1:1;
 return rows.slice().sort((a,b)=>{const av=sort==='time'?Date.parse(a.time):a[sort],bv=sort==='time'?Date.parse(b.time):b[sort];return (typeof av==='number'&&typeof bv==='number'?av-bv:String(av??'').localeCompare(String(bv??'')))*direction||a.number-b.number;});
}
function filteredPacketStatistics(url){
 if(!url.searchParams.get('filter')&&!url.searchParams.get('query')&&!url.searchParams.get('protocol'))return packetStats;
 const rows=filteredPackets(url),timed=rows.filter(row=>row.time&&!row.time.startsWith('0001-')&&Number.isFinite(Date.parse(row.time))),times=timed.map(row=>Date.parse(row.time)),protocols={};
 for(const row of rows)protocols[row.protocol]=(protocols[row.protocol]||0)+1;
 const start=times.length?Math.min(...times):null,end=times.length?Math.max(...times):null;
 const timeline=packetStats.timeline.map((bucket,index)=>{const members=timed.filter(row=>Date.parse(row.time)>=Date.parse(bucket.time)&&(Date.parse(row.time)<Date.parse(bucket.endTime)||index===packetStats.timeline.length-1&&Date.parse(row.time)===Date.parse(bucket.endTime)));return {...bucket,packets:members.length,bytes:members.reduce((sum,row)=>sum+row.length,0)};}).filter(bucket=>bucket.packets);
 return {...packetStats,protocols,bytes:rows.reduce((sum,row)=>sum+row.length,0),timedBytes:timed.reduce((sum,row)=>sum+row.length,0),expert:rows.filter(row=>row.expert?.length).length,timedPackets:timed.length,untimedPackets:rows.length-timed.length,started:start===null?undefined:new Date(start).toISOString(),finished:end===null?undefined:new Date(end).toISOString(),duration:start===null?0:(end-start)/1000,timeline};
}
